WITH base AS (SELECT *, LOWER(channel) AS channel_lower, FLOOR(discount_pct) AS discount_pct_whole, COALESCE(channel, 'DIRECT') AS channel_filled FROM promotions WHERE ends_on > DATE '2023-10-15'), matched AS (SELECT src.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM base src LEFT JOIN promotions pr ON src.channel <=> pr.channel AND src.ends_on BETWEEN pr.starts_on AND pr.ends_on), with_windows AS (SELECT *, AVG(promotion_discount_pct) OVER w_grp AS running_avg_promotion_discount_pct, SUM(promotion_discount_pct) OVER w_grp AS running_sum_promotion_discount_pct, MAX(promotion_discount_pct) OVER w_grp AS running_max_promotion_discount_pct FROM matched WINDOW w_grp AS (PARTITION BY promotion_promo_code ORDER BY ends_on, id, promo_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), attributed AS (SELECT src.*, pr.id AS promo_id_2, pr.promo_code AS promotion_promo_code_2, pr.discount_pct AS promotion_discount_pct_2 FROM with_windows src LEFT JOIN promotions pr ON COALESCE(src.channel, 'store') = pr.channel AND src.starts_on >= pr.starts_on AND src.starts_on <= DATE_ADD(pr.ends_on, 3)) SELECT id, channel, starts_on, ends_on, discount_pct, channel_lower, discount_pct_whole, promo_id, promotion_promo_code FROM attributed ORDER BY promo_id DESC NULLS FIRST
